-- Schema of Database/career_counseling.db (SQLite 3)
-- Generated by tools/export_database.py

CREATE TABLE Accounts (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            full_name TEXT NOT NULL,
            email TEXT NOT NULL UNIQUE,
            password_hash TEXT NOT NULL,
            created_at TEXT NOT NULL,
            age INTEGER,
            gender TEXT
        , is_admin INTEGER NOT NULL DEFAULT 0, security_question TEXT, security_answer_hash TEXT, reset_token_hash TEXT, reset_token_expires TEXT);

CREATE TABLE Assessments (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            account_id INTEGER NOT NULL,
            created_at TEXT NOT NULL,
            inputs_json TEXT NOT NULL,
            top_career TEXT, results_json TEXT,
            FOREIGN KEY(account_id) REFERENCES Accounts(id)
        );

CREATE TABLE CareerInterests(
    career_id INTEGER,
    interest_id INTEGER,
    FOREIGN KEY(career_id) REFERENCES Careers(id),
    FOREIGN KEY(interest_id) REFERENCES Interests(id)
);

CREATE TABLE Careers(
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    career_name TEXT,
    education_required TEXT,
    field_required TEXT,
    minimum_percentage REAL,
    interest TEXT,
    description TEXT,
    required_skills TEXT,
    future_scope TEXT,
    average_salary TEXT,
    learning_resources TEXT
, holland_code TEXT);

CREATE TABLE Feedback (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            assessment_id INTEGER NOT NULL UNIQUE,
            account_id INTEGER NOT NULL,
            helpful INTEGER NOT NULL,
            comment TEXT,
            created_at TEXT NOT NULL,
            FOREIGN KEY(assessment_id) REFERENCES Assessments(id),
            FOREIGN KEY(account_id) REFERENCES Accounts(id)
        );

CREATE TABLE Interests(
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    interest_name TEXT UNIQUE
);

CREATE TABLE Meta (key TEXT PRIMARY KEY, value TEXT);

CREATE TABLE Users(
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT,
    age INTEGER,
    gender TEXT,
    education_level TEXT,
    field_of_study TEXT,
    percentage REAL,
    cgpa REAL
);

CREATE INDEX idx_accounts_reset_token ON Accounts(reset_token_hash);

CREATE INDEX idx_assessments_account ON Assessments(account_id);

CREATE INDEX idx_career_interests_career ON CareerInterests(career_id);

CREATE INDEX idx_feedback_account ON Feedback(account_id);

